function setup(){
  createCanvas(640, 640);
  noStroke();
}

function draw(){
  background(0);
  translate(width/2, height/2);
  for(let x = -100; x <= 100; x+=10){
    for(let y = -100; y <= 100; y+=10){
      let d = dist(x, y, 0, 0);
      let d2 = sin(radians(d))*d;
      fill(0, 150, 255);
      push();
      translate(x, y);
      rotate(radians(d + frameCount));
      ellipse(x, y, 5, 5);
      pop();
    } 
  }
}
